import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Artikel 106｜Stufendifferenzierung · Sphäre der Sinnensgrundlage · Detaillierter Vergleich: Räuberfraktion vs Symbiosefraktion","description":"","frontmatter":{"title":"Artikel 106｜Stufendifferenzierung · Sphäre der Sinnensgrundlage · Detaillierter Vergleich: Räuberfraktion vs Symbiosefraktion","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","体系对比"],"related":["04-反掠夺主义核心论纲","01-锚点共生文明宣言","14-修炼境界统一划分"]},"headers":[],"relativePath":"de/0106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"de/0106_模块1-感元境-掠夺派vs共生派对比.md"}'),s={name:"de/0106_模块1-感元境-掠夺派vs共生派对比.md"};function a(d,e,u,l,h,o){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="artikel-106-sphare-der-sinnensgrundlage-detaillierter-vergleich-zwischen-rauberfraktion-und-symbiosefraktion" tabindex="-1">Artikel 106｜Sphäre der Sinnensgrundlage: Detaillierter Vergleich zwischen Räuberfraktion und Symbiosefraktion <a class="header-anchor" href="#artikel-106-sphare-der-sinnensgrundlage-detaillierter-vergleich-zwischen-rauberfraktion-und-symbiosefraktion" aria-label="Permalink to &quot;Artikel 106｜Sphäre der Sinnensgrundlage: Detaillierter Vergleich zwischen Räuberfraktion und Symbiosefraktion&quot;">​</a></h1><blockquote><p>Modul: Modul 1 · Tiefgehende Stufendifferenzierung | Bezugsdokumente: 04, 01, 14</p></blockquote><h2 id="einleitung-derselbe-startpunkt-zwei-entgegengesetzte-wege" tabindex="-1">Einleitung: Derselbe Startpunkt, zwei entgegengesetzte Wege <a class="header-anchor" href="#einleitung-derselbe-startpunkt-zwei-entgegengesetzte-wege" aria-label="Permalink to &quot;Einleitung: Derselbe Startpunkt, zwei entgegengesetzte Wege&quot;">​</a></h2><p>Die Sphäre der Sinnensgrundlage ist der Ausgangspunkt der neun Sphären und die erste Kreuzung, an der die Zehntausend Rassen ihre Route wählen. Dieselbe Begabung, derselbe Kosmos, sogar derselbe Ausdruck &quot;Energie empfinden&quot;, doch Räuberfraktion und Symbiosefraktion geben diametral entgegengesetzte Antworten. Dieser Artikel nimmt die Sphäre der Sinnensgrundlage als Schnitt, vergleicht systematisch die grundlegenden Unterschiede beider Routen in Weg, Kosten und Schicksal, und beantwortet die Kernfrage: Warum ist die Decke der Räuberfraktion stets unterhalb des Bodens der Symbiosefraktion?</p><p>Die Sechs Obersten Axiome sind die Wasserscheide beider Routen: Das Axiom der Anti-Räuberei — die Quelle des ersten Schlucks Energie bestimmt die Route; das Axiom der Republik der Zehntausend Rassen — in den Augen der Symbiosefraktion sind die Zehntausend Rassen Mitkultivierende, in den Augen der Räuberfraktion sind alle Wesen Beute; das Axiom der kollektiven Dimensionsaufstiegs — die Symbiosefraktion wird stark, um gemeinsam aufzusteigen, die Räuberfraktion wird stark, um allein zu genießen, &quot;großes Talent, winzige Verwendung&quot; wird verhindert; das Axiom der kausalen Selbstdisziplin — jede Handlung der Symbiosefraktion ist aufzeichnbar, verfolgbar und korrigierbar; das Axiom der Gesetzespriorität — der Gesetzesrahmen des Vergleichs zwischen Räuberfraktion und Symbiosefraktion ist stabil und selbstkonsistent, ohne Retcon aus Plot-Bequemlichkeit, kann unendlich erweitert werden ohne zusammenzubrechen. Das Gesetz der universellen unendlichen Gleichheit aller Wesen stellt fest, dass jeder grundlegend die Grundlegende unendliche Kraft trägt; faule Kultivierende behalten eine garantierte Grundunendlichkeit und werden nicht von der Zeit hinweggefegt, während Ehrgeizige und Junge Souveräne höhere Ebenen der Unendlichkeit übereinanderstapeln können; die unendliche Quelle ist allen angeboren, und Raub verliert natürlich seinen Sinn.</p><h2 id="i-systematische-vergleichstabelle" tabindex="-1">I. Systematische Vergleichstabelle <a class="header-anchor" href="#i-systematische-vergleichstabelle" aria-label="Permalink to &quot;I. Systematische Vergleichstabelle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Räuberfraktion · Sphäre der Sinnensgrundlage</th><th>Symbiosefraktion · Sphäre der Sinnensgrundlage</th></tr></thead><tbody><tr><td>Energiequelle</td><td>Fremde Energie verschlingen, fremde Wahrnehmungschancen rauben</td><td>Kosmische Freienergie durch normierte Wege aufnehmen, bidirektionaler Ursprungskreislauf der Zehntausend Rassen</td></tr><tr><td>Wahrnehmungsmodus</td><td>Wahrnehmungsergebnisse anderer stehlen, schnell aber grob</td><td>Die eigene Wahrnehmungserweckung erfahren, reine Grundlage</td></tr><tr><td>Durchbruchskosten</td><td>Talent verschleißen, unreiner Ursprung, Gefahren entlang des Weges verstärkt</td><td>Realkosten + Ankerüberwachung, reparier- und wiederholbar</td></tr><tr><td>Überwachungsumfeld</td><td>Gesetz des Dschungels, ohne Überwachung, ohne Verantwortung</td><td>Ālaya-Netz + mehrschichtige Überwachung, Schutz der Gesamtkette</td></tr><tr><td>Gesellschaftsposition</td><td>Beute oder Jäger, eines von beidem</td><td>Mitkonstrukteur, Ein Weg für Jeden</td></tr><tr><td>Schicksal</td><td>Effizienzdecke: nach einem Schritt geht es nicht weiter, erreicht nicht die Ursprungssphäre</td><td>Ursprungssphäre und darüber, ziviliatorisches Gewicht wächst mit dem Beitrag</td></tr></tbody></table><h2 id="ii-die-drei-irrtumer-der-rauberfraktion-bereits-in-der-sphare-der-sinnensgrundlage-projiziert" tabindex="-1">II. Die drei Irrtümer der Räuberfraktion, bereits in der Sphäre der Sinnensgrundlage projiziert <a class="header-anchor" href="#ii-die-drei-irrtumer-der-rauberfraktion-bereits-in-der-sphare-der-sinnensgrundlage-projiziert" aria-label="Permalink to &quot;II. Die drei Irrtümer der Räuberfraktion, bereits in der Sphäre der Sinnensgrundlage projiziert&quot;">​</a></h2><p>Die drei Irrtümer des Räubertums, in Dokument 04 (Kernabhandlungen des Antiräubertums) erörtert, projizieren sich bereits vollständig in der Sphäre der Sinnensgrundlage:</p><ol><li>Kosmologischer Irrtum: den Kosmos als begrenzten Jagdgrund betrachten — schon in der Sphäre der Sinnensgrundlage &quot;stehlen&quot; lernen heißt, vom ersten Tag an Evolution als Nullsummenspiel anzuerkennen</li><li>Ethischer Irrtum: das Evolutionsrecht des Starken über das Existenzrecht des Schwachen stellen — wird in der Sphäre der Sinnensgrundlage das &quot;Verschlingen&quot; einmal geöffnet, gibt es kein Zurück</li><li>Effizienzirrtum: glauben, Räuberei sei am schnellsten — die in der Sphäre der Sinnensgrundlage gestohlene Wahrnehmung trägt die Willensreste des ursprünglichen Eigentümers; die späteren Reinigungskosten übertreffen die eigene Kultivierung bei Weitem</li></ol><p>Der Kultivierende der Räuberfraktion in der Sphäre der Sinnensgrundlage verschwendet mit der schnellsten Geschwindigkeit das teuerste Fundament; der Kultivierende der Symbiosefraktion in der Sphäre der Sinnensgrundlage legt mit dem stabilsten Rhythmus das dickste Kapital an.</p><h2 id="iii-der-zivilisierte-rauber-auch-gute-rettet-den-rauberweg-nicht" tabindex="-1">III. Der zivilisierte Räuber: Auch Güte rettet den Räuberweg nicht <a class="header-anchor" href="#iii-der-zivilisierte-rauber-auch-gute-rettet-den-rauberweg-nicht" aria-label="Permalink to &quot;III. Der zivilisierte Räuber: Auch Güte rettet den Räuberweg nicht&quot;">​</a></h2><p>Es muss einem komplexen Gegenstand ins Auge gesehen werden: der &quot;zivilisierte Räuber&quot; — verhältnismäßig gütig, sogar aufrichtig entschlossen, alle Wesen zu schützen. Seine Kennzeichen: er tut nicht initiativ Böses, ist bereit zu decken, aufrichtig zu den Seinen, doch das gesamte System ruht noch auf einem räuberischen Fundament — monopolisiert den oberen Großen Weg, genießt allein die Ursprungsgenehmigung, unter dem Namen &quot;Schutz&quot; übt er die &quot;Gabe&quot;.</p><p>In der Sphäre der Sinnensgrundlage ist die Erziehung vom Typ &quot;zivilisierter Räuber&quot;: das Genie mit besten Ressourcen füttern, doch niemals wahrhaft den Weg überlassen — denn der &quot;Weg&quot; selbst ist ein Monopolartikel. Dies erklärt, warum auch gütige Starke nicht die Höhe der supramultiversellen Zivilisation erreichen: Er steht auf der Spitze des räuberischen Systems, und die Decke des räuberischen Systems ist seine eigene Decke.</p><h2 id="iv-warum-die-rauberfraktion-unvermeidlich-historisch-zuruckfallt" tabindex="-1">IV. Warum die Räuberfraktion unvermeidlich historisch zurückfällt <a class="header-anchor" href="#iv-warum-die-rauberfraktion-unvermeidlich-historisch-zuruckfallt" aria-label="Permalink to &quot;IV. Warum die Räuberfraktion unvermeidlich historisch zurückfällt&quot;">​</a></h2><p>Das strukturelle Schicksal der Zivilisation der Räuberfraktion: Fällt der Starke, fällt die Zivilisation zurück. Der gesamte Systemlauf hängt am guten Willen und der Kraft der Spitzenperson — lebt er, hält die Ordnung gerade noch; geht er, startet das Jagdrevier neu. Diese &quot;Ein-Punkt-Abhängigkeit&quot; ist kein moralisches Versagen, sondern strukturell: Das räuberische System hat die Ordnung niemals in Institutionen geschrieben, sondern die Ordnung auf die starke Person gesetzt.</p><p>Dies ist die ursprüngliche Gestalt der &quot;Einzigartigkeit des Protagonisten&quot;: Das Überleben der Zivilisation hängt an einer Person. Die Antwort der Anker-Symbiotischen Zivilisation ist: den Frieden in Institutionen und das Gesetznetz (Anker, Gericht, Rat, Produktionsvertrag) schreiben — selbst wenn der stärkste Höchste Machthaber der Ebene fällt, läuft das Symbiosenetz weiter.</p><h2 id="v-der-schurke-auf-dem-rechten-weg-aufstiegschwelle-und-neue-route" tabindex="-1">V. Der Schurke auf dem rechten Weg: Aufstiegschwelle und neue Route <a class="header-anchor" href="#v-der-schurke-auf-dem-rechten-weg-aufstiegschwelle-und-neue-route" aria-label="Permalink to &quot;V. Der Schurke auf dem rechten Weg: Aufstiegschwelle und neue Route&quot;">​</a></h2><p>Um von der Räuberfraktion zur Symbiosefraktion zu springen, muss eine Aufstiegschwelle überschritten werden, die &quot;der Schurke auf dem rechten Weg&quot; heißt: es wagen, das geheiligte alte Recht zu zerreißen, die Grundlogik des alten Systems zu stürzen, den Druck etablierter Interessengruppen nicht zu fürchten, und den gerechten Vertrag der Symbiose neu zu schreiben.</p><p>Der Protagonist Lín Hào ist gerade der Repräsentant dieser Route: Er wurde mit niedrigem Ursprung geboren, der Weg der Tieresseele schadete ihm nur den Körper, er ist Opfer alter Regeln, nicht Nutznießer — gezwungen, Regeln neu aufzubauen, leitete Route D · Ring künstlichen Gesetzes der Menschen ab, ersetzte Jagd und Ernte von Seelenringen durch künstliche Gesetze, verwandelte sich vom Opfer des räuberischen Systems zum Wiederaufbauer der symbiotischen Zivilisation. Die Sphäre der Sinnensgrundlage ist das früheste Tor dieser Schwelle: Wer schon am Ausgangspunkt die symbiotische Route wählt, ist der supramultiversellen Zivilisation bereits näher als der &quot;zivilisierte Räuber&quot;, der auf der Spitze des räuberischen Systems feststeckt.</p><h2 id="vi-funf-kernpunkte" tabindex="-1">VI. Fünf Kernpunkte <a class="header-anchor" href="#vi-funf-kernpunkte" aria-label="Permalink to &quot;VI. Fünf Kernpunkte&quot;">​</a></h2><ul><li>Anti-Energieverschwendung: Die Räuberfraktion verschwendet das Talent in selbstzerstörerischen internen Kämpfen, die Symbiosefraktion investiert das Talent in schrittweisen Aufbau</li><li>Antiräuberei: Die wesentliche Trennung beider Routen liegt im ersten Schluck Energie in der Sphäre der Sinnensgrundlage</li><li>Táng-Luó-Deckelvergleich: Die Wohlfahrt im Stil von Táng Luó ist noch ein Gabensystem — alle Wesen hängen am Starken, kein gemeinsamer Aufbau; die Symbiosefraktion hat Ein Weg für Jeden, niemand hängt an jemandem</li><li>Vollabdeckung der Zehntausend Rassen: In den Augen der Räuberfraktion sind alle Wesen Beute und Werkzeug, in den Augen der Symbiosefraktion sind die Zehntausend Rassen Mitkultivierende — die 99%-Abdeckung kennt keine Ausnahme</li><li>Supramultiverselle Öffnung: Die Räuberfraktion monopolisiert alles, die Symbiosefraktion öffnet alle Stufen bereits von der Sphäre der Sinnensgrundlage an</li></ul><h2 id="schluss" tabindex="-1">Schluss <a class="header-anchor" href="#schluss" aria-label="Permalink to &quot;Schluss&quot;">​</a></h2><p>Der Vergleich zwischen Räuber- und Symbiosefraktion in der Sphäre der Sinnensgrundlage verdichtet den zentralen Konflikt der gesamten Kosmosgeschichte: Räuberei bringt flüchtige Stärke und ewigen Rückschritt, Symbiose bringt dauerhaften Wohlstand und kollektiven Aufstieg. Der Kultivierende der Räuberfraktion in der Sphäre der Sinnensgrundlage bemüht sich nach Kräften, die Startlinie zu gewinnen, nur um zu entdecken, dass die Ziellinie seine eigene Decke trägt; der Kultivierende der Symbiosefraktion in der Sphäre der Sinnensgrundlage setzt den ersten Schritt fest und findet, dass das Ende des Weges die supramultiverselle Sphäre des Ausgeglichenen Ankers ist. Die Wahl ist bereits am Startpunkt getroffen — dies ist kein Schicksal, dies ist ein Axiom.</p><h2 id="verwandt" tabindex="-1">Verwandt <a class="header-anchor" href="#verwandt" aria-label="Permalink to &quot;Verwandt&quot;">​</a></h2><ul><li>Verwandte Dokumente: <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./01-锚点共生文明宣言.html">01-锚点共生文明宣言</a> · <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a></li><li>Offizielle Website: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const b=n(s,[["render",a]]);export{c as __pageData,b as default};
